using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class OperationalGrid {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Transform root;
 static bool Clear(float x,float z){var p=new Vector3(x,-81.99f,z);return !Physics.OverlapCapsule(p+Vector3.up*.42f,p+Vector3.up*1.58f,.38f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.enabled&&c.transform.IsChildOf(root))&&Physics.RaycastAll(p+Vector3.up*.2f,Vector3.down,.5f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root));}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;Physics.SyncTransforms();var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_OperationalDetail/plan.json"));var grids=new Dictionary<string,object>();int total=0;foreach(var entry in (JObject)plan["rooms"]){var r=entry.Value;float step=.18f,cx=(float)r["x"],cz=-(float)r["v"];int half=Mathf.CeilToInt(((float)r["r"]+.7f)/step),size=2*half+1;var flags=new char[size*size];int free=0;for(int z=0;z<size;z++)for(int x=0;x<size;x++){bool ok=Clear(cx+(x-half)*step,cz+(z-half)*step);flags[z*size+x]=ok?'1':'0';if(ok)free++;}grids[entry.Key]=new{step,size,half,cx,cz,free,flags=new string(flags)};total+=size*size;}File.WriteAllText(Repo+"/SourceAssets/B5_OperationalDetail/grids.json",JsonConvert.SerializeObject(grids));return new{rooms=grids.Count,samples=total,sceneUnchanged=!s.isDirty};}
}
